def numSubmat(mat):
    rows, cols = len(mat), len(mat[0])
    heights = [0] * cols
    total = 0
    for r in range(rows):
        for c in range(cols):
            heights[c] = heights[c] + 1 if mat[r][c] else 0
        for c in range(cols):
            if heights[c] == 0:
                continue
            min_height = heights[c]
            for k in range(c, -1, -1):
                if heights[k] == 0:
                    break
                min_height = min(min_height, heights[k])
                total += min_height
    return total
